import React, { useState } from 'react';
import { X, Copy, Check, Download, Info } from 'lucide-react';

interface RsnModalProps {
  isOpen: boolean;
  onClose: () => void;
}

export const RsnModal: React.FC<RsnModalProps> = ({ isOpen, onClose }) => {
  const [serverHost, setServerHost] = useState('192.168.10.45');
  const [revitYear, setRevitYear] = useState('2025');
  const [copied, setCopied] = useState(false);

  if (!isOpen) return null;

  const generatedIni = `; Revit Server Network Configuration
; Generated by OpenRevitServer
; Path: C:\\ProgramData\\Autodesk\\RevitServer${revitYear}\\Config\\RSN.ini

${serverHost.trim()}
`;

  const handleCopy = () => {
    navigator.clipboard.writeText(generatedIni);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleDownload = () => {
    const blob = new Blob([generatedIni], { type: 'text/plain;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = 'RSN.ini';
    link.click();
    URL.revokeObjectURL(url);
  };

  return (
    <div className="fixed inset-0 z-50 bg-black/75 backdrop-blur-sm flex items-center justify-center p-4">
      <div className="bg-neutral-900 border border-neutral-800 rounded-2xl max-w-lg w-full p-6 space-y-5 shadow-2xl">
        <div className="flex items-center justify-between border-b border-neutral-800 pb-3">
          <div>
            <h3 className="text-base font-bold text-white">Генератор конфигурации RSN.ini</h3>
            <p className="text-xs text-neutral-400">Конфигурационный файл для подключения клиента Autodesk Revit</p>
          </div>
          <button
            onClick={onClose}
            className="p-1 rounded-lg hover:bg-neutral-800 text-neutral-400 hover:text-white"
          >
            <X className="w-4 h-4" />
          </button>
        </div>

        <div className="space-y-4">
          <div className="space-y-1.5">
            <label className="text-xs font-semibold text-neutral-300">IP-адрес или Hostname Linux сервера:</label>
            <input
              type="text"
              value={serverHost}
              onChange={(e) => setServerHost(e.target.value)}
              placeholder="e.g. 192.168.10.45 или revit.company.local"
              className="w-full bg-neutral-950 border border-neutral-800 rounded-lg px-3 py-2 text-xs text-neutral-200 font-mono focus:outline-none focus:border-amber-500"
            />
          </div>

          <div className="space-y-1.5">
            <label className="text-xs font-semibold text-neutral-300">Версия Autodesk Revit:</label>
            <div className="grid grid-cols-4 gap-2">
              {['2023', '2024', '2025', '2026'].map((year) => (
                <button
                  key={year}
                  onClick={() => setRevitYear(year)}
                  className={`py-1.5 text-xs font-medium rounded-lg border transition-colors ${
                    revitYear === year
                      ? 'bg-neutral-800 border-amber-500 text-amber-400'
                      : 'bg-neutral-950 border-neutral-800 text-neutral-400 hover:text-white'
                  }`}
                >
                  {year}
                </button>
              ))}
            </div>
          </div>

          <div className="p-3 rounded-lg bg-neutral-950 border border-neutral-800 font-mono text-xs text-neutral-300 space-y-1">
            <div className="text-[11px] text-neutral-500">Куда сохранить файл на Windows клиенте:</div>
            <div className="text-amber-400/90 break-all select-all">
              C:\ProgramData\Autodesk\RevitServer{revitYear}\Config\RSN.ini
            </div>
          </div>

          <div className="space-y-1.5">
            <div className="flex items-center justify-between text-xs text-neutral-400">
              <span>Содержимое RSN.ini:</span>
              <button
                onClick={handleCopy}
                className="hover:text-white flex items-center gap-1 font-mono text-[11px]"
              >
                {copied ? <Check className="w-3 h-3 text-emerald-400" /> : <Copy className="w-3 h-3" />}
                <span>{copied ? 'Скопировано' : 'Копировать'}</span>
              </button>
            </div>
            <pre className="p-3 rounded-lg bg-neutral-950 border border-neutral-800 font-mono text-xs text-emerald-400">
              {generatedIni}
            </pre>
          </div>
        </div>

        <div className="flex items-center justify-end gap-3 pt-3 border-t border-neutral-800">
          <button
            onClick={onClose}
            className="px-4 py-2 rounded-lg bg-neutral-800 hover:bg-neutral-700 text-neutral-300 text-xs font-semibold"
          >
            Закрыть
          </button>
          <button
            onClick={handleDownload}
            className="px-4 py-2 rounded-lg bg-amber-500 hover:bg-amber-400 text-neutral-950 text-xs font-bold flex items-center gap-1.5 shadow-sm"
          >
            <Download className="w-3.5 h-3.5" />
            <span>Скачать RSN.ini</span>
          </button>
        </div>
      </div>
    </div>
  );
};
